interfaces:
class URLShortener(Protocol):
    def shorten(self, long_url: str, custom_alias: str | None = None) -> ShortLink: ...
    def resolve(self, code: str) -> ShortLink | None: ...

class CodeGenerator(Protocol):
    def next_code(self) -> str: ...
    def is_valid(self, code: str) -> bool: ...

class Redirector(Protocol):
    def redirect(self, code: str) -> RedirectResult: ...

RedirectResult = tuple[int, str | None]  # (status, location)

class ClickRecorder(Protocol):
    def record(self, event: ClickEvent) -> None: ...

class StatsReader(Protocol):
    def stats_for(self, code: str) -> ClickStats: ...

class RateLimiter(Protocol):
    def check(self, key: str, cost: int = 1) -> RateDecision: ...

class RateDecision(Protocol):
    allowed: bool
    remaining: int
    retry_after_s: float
